inline uint8_t tb01_byte(size_t offset, uint8_t stock) {
  if (offset >= 0xc08 && offset < 0xc08 + sizeof(TB01_HOOK_SOUND)) return TB01_HOOK_SOUND[offset - 0xc08];
  if (offset >= 0x5e5e && offset < 0x5e5e + sizeof(TB01_HOOK_SLEEP)) return TB01_HOOK_SLEEP[offset - 0x5e5e];
  if (offset >= 0x6c02 && offset < 0x6c02 + sizeof(TB01_HOOK_INIT)) return TB01_HOOK_INIT[offset - 0x6c02];
  if (offset >= 0x6c34 && offset < 0x6c34 + sizeof(TB01_HOOK_ROUTE)) return TB01_HOOK_ROUTE[offset - 0x6c34];
  if (offset >= 0x6c52 && offset < 0x6c52 + sizeof(TB01_HOOK_TICK)) return TB01_HOOK_TICK[offset - 0x6c52];
  if (offset >= 0x7810 && offset < 0x7810 + sizeof(TB01_CANDIDATE)) return TB01_CANDIDATE[offset - 0x7810];
  return rs01_byte(offset, stock);
}
inline bool apply_tb01(uint8_t *image, size_t size) {
  if (!image || size != IMAGE_SIZE) return false;
  const uint8_t before_hook_sound[] = {0xf8,0xb5,0x31,0x4d,0x04,0x46,0x0f,0x46};
  if (std::memcmp(image + 0xc08, before_hook_sound, sizeof(before_hook_sound))) return false;
  const uint8_t before_hook_sleep[] = {0xfe,0xf7,0x83,0xff};
  if (std::memcmp(image + 0x5e5e, before_hook_sleep, sizeof(before_hook_sleep))) return false;
  const uint8_t before_hook_init[] = {0x00,0xf0,0x4d,0xf8};
  if (std::memcmp(image + 0x6c02, before_hook_init, sizeof(before_hook_init))) return false;
  const uint8_t before_hook_route[] = {0x00,0xf0,0xd4,0xf9};
  if (std::memcmp(image + 0x6c34, before_hook_route, sizeof(before_hook_route))) return false;
  const uint8_t before_hook_tick[] = {0x00,0xf0,0x35,0xf8};
  if (std::memcmp(image + 0x6c52, before_hook_tick, sizeof(before_hook_tick))) return false;
  for (size_t i = 0x7810; i < IMAGE_SIZE; ++i) if (image[i] != 255) return false;
  std::memcpy(image + 0xc08, TB01_HOOK_SOUND, sizeof(TB01_HOOK_SOUND));
  std::memcpy(image + 0x5e5e, TB01_HOOK_SLEEP, sizeof(TB01_HOOK_SLEEP));
  std::memcpy(image + 0x6c02, TB01_HOOK_INIT, sizeof(TB01_HOOK_INIT));
  std::memcpy(image + 0x6c34, TB01_HOOK_ROUTE, sizeof(TB01_HOOK_ROUTE));
  std::memcpy(image + 0x6c52, TB01_HOOK_TICK, sizeof(TB01_HOOK_TICK));
  std::memcpy(image + 0x7810, TB01_CANDIDATE, sizeof(TB01_CANDIDATE));
  return true;
}
// Exact TB01 input and restored R7 output hashes are required at the caller.
inline bool remove_tb01(uint8_t *image, size_t size) {
  if (!image || size != IMAGE_SIZE) return false;
  if (std::memcmp(image + 0xc08, TB01_HOOK_SOUND, sizeof(TB01_HOOK_SOUND))) return false;
  if (std::memcmp(image + 0x5e5e, TB01_HOOK_SLEEP, sizeof(TB01_HOOK_SLEEP))) return false;
  if (std::memcmp(image + 0x6c02, TB01_HOOK_INIT, sizeof(TB01_HOOK_INIT))) return false;
  if (std::memcmp(image + 0x6c34, TB01_HOOK_ROUTE, sizeof(TB01_HOOK_ROUTE))) return false;
  if (std::memcmp(image + 0x6c52, TB01_HOOK_TICK, sizeof(TB01_HOOK_TICK))) return false;
  if (std::memcmp(image + 0x7810, TB01_CANDIDATE, sizeof(TB01_CANDIDATE))) return false;
  const uint8_t before_hook_sound[] = {0xf8,0xb5,0x31,0x4d,0x04,0x46,0x0f,0x46};
  std::memcpy(image + 0xc08, before_hook_sound, sizeof(before_hook_sound));
  const uint8_t before_hook_sleep[] = {0xfe,0xf7,0x83,0xff};
  std::memcpy(image + 0x5e5e, before_hook_sleep, sizeof(before_hook_sleep));
  const uint8_t before_hook_init[] = {0x00,0xf0,0x4d,0xf8};
  std::memcpy(image + 0x6c02, before_hook_init, sizeof(before_hook_init));
  const uint8_t before_hook_route[] = {0x00,0xf0,0xd4,0xf9};
  std::memcpy(image + 0x6c34, before_hook_route, sizeof(before_hook_route));
  const uint8_t before_hook_tick[] = {0x00,0xf0,0x35,0xf8};
  std::memcpy(image + 0x6c52, before_hook_tick, sizeof(before_hook_tick));
  std::memset(image + 0x7810, 255, 2032);
  return true;
}
